SourceCode.Declaration:
using System.ComponentModel.Composition;

/// <summary>
/// Enables the users listed for the environment after a copy disabled them. Every other user keeps its state.
/// </summary>
[ExportAttribute(identifierStr(Dynamics.AX.Application.BDRITaskType))]
[ExportMetadata(classStr(BDRITaskType), 'EnableUsers')]
public final class BDRTaskTypeEnableUsers implements BDRITaskType
{
    public const BDRTaskTypeName Name = 'EnableUsers';
}

Method.Source:
public BDRTaskTypeRegistrationItem registration()
{
    return BDRTaskTypeRegistrationItem::construct(BDRTaskTypeEnableUsers::Name, literalStr("@BDR:TaskEnableUsers"), 10, false, menuItemDisplayStr(BDRUserToEnable));
}

    public void run(BDRTaskContext _context)
    {
        BDREnvironmentId environmentId = _context.environmentId();
        UserInfo userInfo;
        BDRUserToEnable userToEnable;
        BDRRecordsAffected enabled;

        ttsbegin;

        // Only the users listed for the environment; every other user keeps its state.
        while select forupdate userInfo
            where userInfo.enable == NoYes::No
            exists join userToEnable
                where userToEnable.UserId == userInfo.id
                    && userToEnable.EnvironmentId == environmentId
        {
            userInfo.enable = NoYes::Yes;
            userInfo.update();
            enabled++;
        }

        ttscommit;

        _context.addRecordsAffected(enabled);
        _context.logInfo(strFmt("@BDR:MsgRecordsUpdated", enabled));
    }
